# Import (F1): BDS loads the full content skeleton generated by tools/import/run.ps1 (523 blocks with
# their frozen states, every item, block item, spawn egg and entity, the recipes, lang and data)
# with no Bedrock content-log error (run.ps1 fails the run on any "ERR [Server] [<category>]" line),
# and the import.* selftests confirm that the game registered all of it and can place every block.
Wait-LogLine 'GloamingForest world ready' 120 | Out-Null

$r = Invoke-SelfTest 'import.*' -TimeoutSeconds 900
if ($r.Fail -gt 0) { throw "$($r.Fail) import selftest(s) failed" }
# every import selftest by name (src/feature/ext/import/{ImportTests,HarvestTests}.cpp): one that stopped registering fails the run
$expected = @('import.blocks', 'import.items', 'import.entities', 'import.lang_and_data', 'import.java_states',
    'import.rotations', 'import.light', 'import.behaviour', 'import.bool_defaults', 'import.place_blocks',
        'import.harvest_tags', 'import.harvest_mining', 'import.harvest_drops')
$missing = @($expected | Where-Object { $r.Passed -notcontains $_ })
if ($missing.Count -gt 0) { throw "import selftest(s) did not pass: $($missing -join ', ') (passed: $($r.Passed -join ', '))" }

# Content-log warnings about the skeleton are reported for the spike (S7), errors fail the run.
$warn = @(Get-ServerLog | Where-Object { $_ -match '\bWARN\]?\s?\[Server\]\s*(<[^>]*>\s*)?\[[A-Za-z][A-Za-z ]*\]' })
Write-Step "content-log warnings: $($warn.Count)"
$warn | Select-Object -First 20 | ForEach-Object { Write-Step "  $_" }
